const input = $input.first().json;
const config = input.config || input;
const now = new Date();
const stamp = now.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}Z$/, 'Z').replace('T', '-');
const random = Math.random().toString(36).slice(2, 8);
const runId = `n8n-${stamp}-${random}`;
return [{ json: {
  ...input,
  config,
  run_id: runId,
  trigger_source: 'manual_n8n'
}}];

const worker = $input.first().json || {};
const context = $('Build Full Run Context').first().json;
let previous = {};
try { previous = $('Wait 20s for Worker Run').item.json || {}; } catch (error) {}
const elapsedMs = Date.now() - Number(context.orchestration_started_at_ms || Date.now());
const priorErrors = Number(previous.consecutive_polling_errors || 0);
const valid = new Set(['running', 'completed', 'completed_with_errors', 'failed']);
const status = String(worker.status || '');
const statusCode = Number(worker.statusCode || worker.error?.httpCode || worker.error?.statusCode || 0);
const summary = worker.summary || {};
const output = { run_id: worker.run_id || context.run_id, config: context.config, worker: { status: status || 'unknown', error_code: worker.error_code || null, error_summary: worker.error_summary || null, collection_stats: { unique_vacancy_count: summary.collection_unique_vacancy_count }, filter_stats: { processed_count: summary.filter_processed_count }, enrichment_stats: { enriched_count: summary.enriched_count }, duration_ms: summary.duration_ms }, persistence_stats: { persisted_count: summary.persisted_count, status: summary.persistence_status, failed_count: 0 }, warnings: Array.isArray(summary.warnings) ? summary.warnings : [], partial_failures: Array.isArray(summary.partial_failures) ? summary.partial_failures : [], terminal: false, result_available: false, consecutive_polling_errors: 0, orchestration_elapsed_ms: elapsedMs, failure_code: null, failure_summary: null };
if (valid.has(status)) { if (status === 'running') { output.consecutive_polling_errors = 0; } else { output.terminal = true; output.result_available = worker.result_available === true; if (status === 'completed_with_errors' && output.partial_failures.length === 0) output.partial_failures.push({ code: 'partial_failures', count: 1, summary: 'Pipeline завершился с частичными ошибками' }); if (status === 'failed') { output.failure_code = worker.error_code || 'worker_pipeline_failed'; output.failure_summary = worker.error_summary || 'Worker pipeline завершился ошибкой'; } else if (!output.result_available) { output.failure_code = worker.error_code || 'worker_result_unavailable'; output.failure_summary = worker.error_summary || 'Worker не вернул пригодный для сохранения результат'; } } } else if (statusCode === 404) { output.terminal = true; output.failure_code = 'worker_run_not_found'; output.failure_summary = 'Worker не нашёл запущенный pipeline'; } else if (elapsedMs >= 7200000) { output.terminal = true; output.failure_code = 'worker_polling_deadline'; output.failure_summary = 'Превышен срок ожидания Worker pipeline'; } else { output.consecutive_polling_errors = priorErrors + 1; if (output.consecutive_polling_errors >= 3) { output.terminal = true; output.failure_code = 'worker_polling_failed'; output.failure_summary = 'Не удалось получить статус Worker pipeline'; } }
return [{ json: output }];

function nodeItems(name) {
  try { return $(name).all().map(item => item.json); } catch (error) {}
  try { return $items(name).map(item => item.json); } catch (error) {}
  return [];
}
function firstNode(name) { return nodeItems(name)[0] || {}; }
function escapeHtml(value) {
  return String(value || '').replace(/[&<>"]/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[char]));
}
function compact(values, limit = 6) {
  return [...new Set((values || []).filter(Boolean).map(String))].slice(0, limit);
}
function riskLabel(code) {
  const labels = {
    salary_low_strong: 'Низкая зарплата',
    salary_low_moderate: 'Зарплата ниже ожиданий',
    responsibility_stretch: 'Повышенная ответственность',
    english_required: 'Требуется английский',
    office_outside_samara: 'Офис вне Самары',
    relocation_required: 'Нужна релокация',
    travel_required: 'Командировки'
  };
  return labels[code] || code;
}
function priorityValue(analysis) { return String(analysis.priority || ''); }
function vacancyOf(analysis) { return analysis.vacancy_snapshot || {}; }
const context = firstNode('Build Run Context');
const run = firstNode('Get Current Run');
const worker = context.worker || {};
const analyses = Array.isArray(run.analyses) ? run.analyses : [];
const priorityCounts = { P1: 0, P2: 0, P3: 0, ALT: 0 };
for (const analysis of analyses) {
  const priority = priorityValue(analysis);
  if (priority in priorityCounts) priorityCounts[priority] += 1;
}
const order = { P1: 0, P2: 1, ALT: 2, P3: 3 };
const top = analyses
  .filter(analysis => ['P1', 'P2', 'ALT'].includes(priorityValue(analysis)))
  .sort((left, right) => {
    const priorityDelta = (order[priorityValue(left)] ?? 99) - (order[priorityValue(right)] ?? 99);
    if (priorityDelta) return priorityDelta;
    const scoreDelta = Number(right.final_score || 0) - Number(left.final_score || 0);
    if (scoreDelta) return scoreDelta;
    return Number(left.id || 0) - Number(right.id || 0);
  })
  .slice(0, Number(context.config?.top_vacancy_limit || 10));
const topHtml = top.map(analysis => {
  const vacancy = vacancyOf(analysis);
  const reason = analysis.semantic_snapshot?.short_reason || analysis.summary || '—';
  const risks = compact((analysis.risks || []).map(riskLabel)).join(', ') || '—';
  const link = vacancy.url
    ? '<a href="' + escapeHtml(vacancy.url) + '">Открыть вакансию</a>'
    : 'Ссылка недоступна';
  return '<li><b>[' + escapeHtml(priorityValue(analysis)) + '] ' + escapeHtml(analysis.final_score ?? '—') + ' — ' + escapeHtml(vacancy.title || 'Вакансия') + '</b><br>' +
    escapeHtml(vacancy.company || '—') + '<br>' +
    'Причина: ' + escapeHtml(reason) + '<br>' +
    'Риски: ' + escapeHtml(risks) + '<br>' +
    link + '</li>';
}).join('');
const warnings = [...(context.warnings || [])];
const persisted = worker.persistence_stats?.persisted_count ?? context.persistence_stats?.persisted_count ?? '';
const subjectPrefix = context.mode === 'existing_run_replay'
  ? 'AI Job Automation — повторная отправка дайджеста'
  : 'AI Job Automation — новый запуск';
const subjectDate = new Date().toLocaleDateString('ru-RU', { timeZone: 'Europe/Samara' });
const subject = warnings.length
  ? subjectPrefix + ' — с предупреждениями — ' + subjectDate
  : subjectPrefix + ' — ' + subjectDate;
const html = '<p>Обработка вакансий завершена.</p>' +
  '<p><b>Run:</b> ' + escapeHtml(context.run_id) + '</p>' +
  (context.mode === 'existing_run_replay' ? '<p><b>Режим:</b> повторная отправка дайджеста для существующего run.</p>' : '') +
  (warnings.length ? '<p><b>Предупреждения:</b> ' + escapeHtml(warnings.join('; ')) + '</p>' : '') +
  '<ul>' +
  '<li>Найдено: ' + escapeHtml(worker.collection_stats?.unique_vacancy_count ?? '') + '</li>' +
  '<li>Прошло preliminary filter: ' + escapeHtml(worker.filter_stats?.processed_count ?? '') + '</li>' +
  '<li>Полностью обработано: ' + escapeHtml(worker.enrichment_stats?.enriched_count ?? '') + '</li>' +
  '<li>Сохранено в DB: ' + escapeHtml(persisted) + '</li>' +
  '<li>P1: ' + priorityCounts.P1 + ', P2: ' + priorityCounts.P2 + ', ALT: ' + priorityCounts.ALT + ', P3: ' + priorityCounts.P3 + '</li>' +
  '<li>Длительность Worker: ' + escapeHtml(worker.duration_ms ?? '') + ' ms</li>' +
  '</ul><h3>Top vacancies</h3><ol>' + topHtml + '</ol>';
return [{ json: {
  to: context.config?.email_to,
  subject,
  html,
  text: html.replace(/<[^>]*>/g, ' '),
  run_id: context.run_id
} }];

function nodeItems(name) {
  try { return $(name).all().map(item => item.json); } catch (error) {}
  try { return $items(name).map(item => item.json); } catch (error) {}
  return [];
}
function firstNode(name) { return nodeItems(name)[0] || {}; }
function appendCount(lines, label, value) {
  if (value === null || value === undefined || value === '') return;
  const count = Number(value);
  if (Number.isFinite(count)) lines.push(`${label}: ${count}`);
}
const check = firstNode('Build Run Context');
const run = firstNode('Get Current Run');
const worker = check.worker || {};
const hasAnalyses = Array.isArray(run.analyses);
const selectedCount = hasAnalyses
  ? run.analyses.filter(analysis => ['P1', 'P2', 'ALT'].includes(analysis.priority)).length
  : null;
const lines = [
  check.mode === 'existing_run_replay'
    ? 'AI Job Automation: синхронизация завершена.'
    : 'AI Job Automation: обработка вакансий завершена.'
];
appendCount(lines, 'Обработано', worker.enrichment_stats?.enriched_count ?? worker.filter_stats?.processed_count);
appendCount(lines, 'Отобрано', selectedCount);
return [{ json: { text: lines.join('\n') } }];

const response = $input.first().json || {};
const run = $('Build Run Context').first().json;
const status = Number(response.statusCode || response.status || response.error?.httpCode || 0);
const failed = Boolean(response.error) || response.ok === false || status >= 400;
return [{ json: { run_id: run.run_id, config: run.config, integration_error: failed ? { code: 'gmail_digest_failed', count: 1, summary: 'Не удалось отправить Gmail-дайджест.' } : null } }];

const response = $input.first().json || {};
const run = $('Build Run Context').first().json;
const status = Number(response.statusCode || response.status || response.error?.httpCode || 0);
const failed = Boolean(response.error) || response.ok === false || status >= 400;
return [{ json: { run_id: run.run_id, config: run.config, integration_error: failed ? { code: 'telegram_notification_failed', count: 1, summary: 'Не удалось отправить Telegram-уведомление.' } : null } }];

const check = $input.first().json;
const subject = `AI Job Automation — ошибка поиска — ${new Date().toLocaleDateString('ru-RU')}`;
const html = `<p>Pipeline failed.</p><ul><li>Run: ${check.run_id}</li><li>Stage: ${check.failure_stage || 'unknown'}</li><li>Error: ${check.safe_error || 'see n8n/Worker logs'}</li></ul><p>DB remains source of truth for successfully persisted earlier runs.</p>`;
return [{ json: { to: check.config?.email_to, subject, html, text: html.replace(/<[^>]*>/g, ' '), run_id: check.run_id } }];

function firstNode(name) {
  try { return $(name).first().json || {}; } catch (error) { return { error: { message: `Missing output from ${name}` } }; }
}
function hasError(data) {
  return Boolean(data?.error);
}
function errorText(data) {
  return String(data?.error?.message || data?.message || 'unavailable');
}
const selection = $('Build Selected Profile IDs').first().json;
const config = selection.config;
const runId = selection.run_id || null;
const triggerSource = selection.trigger_source || null;
const orchestrator = firstNode('Preflight Orchestrator');
const worker = firstNode('Preflight Worker');
const ollama = firstNode('Preflight Ollama');
const compute = firstNode('Preflight Compute');
const hhAuth = selection.has_resume_profile ? firstNode('Preflight HH Auth') : { status: 'skipped', component: 'hh_auth', storage_state_available: null };
const hhSession = selection.has_resume_profile ? firstNode('Preflight HH Session') : { status: 'skipped', authenticated: null, resume_context_confirmed: null };
const failures = [];

if (hasError(orchestrator)) {
  failures.push({ component: 'Orchestrator', reason: 'unavailable', detail: errorText(orchestrator) });
} else if (orchestrator.status !== 'ok') {
  failures.push({ component: 'Orchestrator', reason: 'unhealthy status', detail: `status=${orchestrator.status || 'missing'}` });
}

if (hasError(worker)) {
  failures.push({ component: 'Worker API', reason: 'unavailable', detail: errorText(worker) });
} else if (worker.status !== 'ok' || worker.component !== 'worker') {
  failures.push({ component: 'Worker API', reason: 'unhealthy response', detail: `status=${worker.status || 'missing'} component=${worker.component || 'missing'}` });
}

if (hasError(ollama)) {
  failures.push({ component: 'Ollama', reason: 'unavailable', detail: errorText(ollama) });
} else if (ollama.status !== 'ok' || ollama.component !== 'ollama' || ollama.model_available !== true) {
  failures.push({ component: 'Ollama', reason: 'unhealthy', detail: `status=${ollama.status || 'missing'} model_available=${ollama.model_available}` });
}

if (hasError(compute)) {
  failures.push({ component: 'Ollama compute', reason: 'unavailable', detail: errorText(compute) });
} else if (compute.status !== 'ok' || compute.component !== 'ollama_compute' || compute.model_loaded !== true || compute.compute_backend !== 'gpu' || compute.gpu_acceptable !== true) {
  failures.push({ component: 'Ollama compute', reason: 'GPU required', detail: `status=${compute.status || 'missing'} model_loaded=${compute.model_loaded} compute_backend=${compute.compute_backend || 'missing'} gpu_acceptable=${compute.gpu_acceptable} warmup_status=${compute.warmup_status || 'missing'} reason=${compute.reason || 'none'}` });
}

if (selection.has_resume_profile && hasError(hhAuth)) {
  failures.push({ component: 'HH auth', reason: 'unavailable', detail: errorText(hhAuth) });
} else if (selection.has_resume_profile && (hhAuth.status !== 'configured' || hhAuth.component !== 'hh_auth' || hhAuth.storage_state_available !== true)) {
  failures.push({ component: 'HH auth', reason: 'storage state not configured', detail: `status=${hhAuth.status || 'missing'} storage_state_available=${hhAuth.storage_state_available}` });
}

if (selection.has_resume_profile && hasError(hhSession)) {
  failures.push({ component: 'HH session', reason: 'not confirmed', detail: errorText(hhSession) });
} else if (selection.has_resume_profile && (hhSession.status !== 'succeeded' || hhSession.authenticated !== true || hhSession.resume_context_confirmed !== true)) {
  failures.push({ component: 'HH session', reason: 'authentication or resume context not confirmed', detail: `status=${hhSession.status || 'missing'} authenticated=${hhSession.authenticated} resume_context_confirmed=${hhSession.resume_context_confirmed}` });
}

const ok = failures.length === 0;
const firstFailure = failures[0] || null;
return [{
  json: {
    ok,
    config,
    run_id: runId,
    trigger_source: triggerSource,
    failure_stage: ok ? null : 'preflight',
    safe_error: ok ? null : `Preflight failed: ${firstFailure.component} ${firstFailure.reason}`,
    preflight: {
      orchestrator: { status: orchestrator.status || null },
      worker: { status: worker.status || null, component: worker.component || null },
      ollama: { status: ollama.status || null, component: ollama.component || null, model_available: ollama.model_available === true },
      compute: {
        status: compute.status || null,
        model_loaded: compute.model_loaded === true,
        compute_backend: compute.compute_backend || null,
        gpu_acceptable: compute.gpu_acceptable === true,
        warmup_status: compute.warmup_status || null,
        reason: compute.reason || null
      },
      hh_auth: { status: hhAuth.status || null, component: hhAuth.component || null, storage_state_available: hhAuth.storage_state_available === true },
      hh_session: { status: hhSession.status || null, authenticated: hhSession.authenticated === true, resume_context_confirmed: hhSession.resume_context_confirmed === true }
    },
    failures
  }
}];

const input = $input.first().json || {};
const firstFailure = Array.isArray(input.failures) ? input.failures[0] || {} : {};
const component = String(firstFailure.component || '').toLowerCase();
const errorCode = component === 'hh auth' ? 'hh_auth_failed' : component === 'hh session' ? 'hh_session_failed' : component === 'worker api' ? 'worker_unavailable' : component === 'ollama' || component === 'ollama compute' ? 'ollama_unavailable' : component === 'orchestrator' ? 'orchestrator_unavailable' : 'preflight_failed';
return [{ json: { ...input, error_code: errorCode, error_summary: String(input.safe_error || 'Preflight failed').slice(0, 255) } }];

