const input = $input.first().json || {};
const selection = input.profile_selection || {};
const config = input.config || {};

const allowedProfileIds = [
  'ai_resume_recommendations',
  'python_resume_recommendations',
  'test_resume_recommendations',
  'test_expanded_search',
  'ai_automation_keywords',
  'vibecoding_keywords',
  'python_backend_keywords',
  'python_automation_keywords'
];

const resumeProfileIds = new Set([
  'ai_resume_recommendations',
  'python_resume_recommendations',
  'test_resume_recommendations'
]);

for (const [profileId, selected] of Object.entries(selection)) {
  if (typeof selected !== 'boolean') {
    throw new Error(`Search profile selector must be boolean: ${profileId}`);
  }

  if (selected === true && !allowedProfileIds.includes(profileId)) {
    throw new Error(`Unknown search profile selector: ${profileId}`);
  }
}

const profileIds = allowedProfileIds.filter(
  profileId => selection[profileId] === true
);

if (profileIds.length === 0) {
  throw new Error('No search profiles selected');
}

const selectedResumeProfileId = profileIds.find(profileId => resumeProfileIds.has(profileId)) || null;
return [{ json: {
  ...input,
  config: { ...config, profile_ids: profileIds },
  profile_selection: selection,
  has_resume_profile: selectedResumeProfileId !== null,
  selected_resume_profile_id: selectedResumeProfileId
}}];

const input = $input.first().json;
const config = input.config || input;
const existingRunId = String(input.existing_run_id || config.existing_run_id || '').trim();
const runId = String(input.run_id || existingRunId || '').trim();
if (!runId) {
  throw new Error('run_id is required for result and email processing');
}
const replayMode = Boolean(existingRunId) && !input.worker;
const warnings = [...(input.warnings || [])];
return [{
  json: {
    ok: input.ok !== false,
    run_id: runId,
    config,
    worker: input.worker || { status: 'existing_run_replay' },
    persistence_stats: input.persistence_stats || {},
    warnings,
    failure_stage: input.failure_stage || null,
    safe_error: input.safe_error || null,
    mode: replayMode ? 'existing_run_replay' : 'worker_pipeline'
  }
}];

const input = $input.first().json;

const provided = String(
  input.headers?.['x-ai-job-automation-webhook-secret'] || ''
);

const expected = String($env.N8N_WEBHOOK_SECRET || '');

if (!expected || provided !== expected) {
  throw new Error('Webhook authentication failed');
}

return $input.all();

const input = $input.first().json || {};
const request = input.body || input;

if (!request.run_id || request.trigger_source !== 'web_ui' || !request.config || !request.profile_selection) {
  throw new Error('Invalid web run request');
}

return [{
  json: {
    run_id: String(request.run_id),
    trigger_source: 'web_ui',
    config: {
      ...request.config,
      worker_api_url: $env.WORKER_API_URL,
      orchestrator_api_url: $env.ORCHESTRATOR_API_URL
    },
    profile_selection: request.profile_selection
  }
}];

const selection = $input.first().json || {};
const config = $('Config').first().json || {};
return [{ json: { trigger_source: 'manual_n8n', config, profile_selection: selection } }];

const input = $input.first().json || {};
const config = input.config || {};
const runId = String(input.run_id || '').trim();
if (!runId) throw new Error('run_id is required before Worker start');

const profileIds = Array.isArray(config.profile_ids) ? config.profile_ids : [];
return [{ json: {
  ...input,
  run_id: runId,
  trigger_source: String(input.trigger_source || ''),
  orchestration_started_at_ms: Date.now(),
  config,
  profile_selection: input.profile_selection || {},
  profile_ids: profileIds,
  has_resume_profile: input.has_resume_profile === true,
  selected_resume_profile_id: input.selected_resume_profile_id || null,
  worker_request: {
    profile_ids: profileIds,
    max_pages_override: config.max_pages_override,
    max_filter_items_override: config.max_filter_items_override,
    max_enrich_items_override: config.max_enrich_items_override,
    pipeline_run_id: runId
  }
}}];
